    def _parse_field():
        nonlocal i
        field = ""
        escaped = False
        quoted = False
        while i < len(line):
            if escaped:
                if line[i] == '"':
                    field += '"'
                else:
                    field += line[i]
                escaped = False
            elif line[i] == '"':
                quoted = not quoted
            elif line[i] == ',' and not quoted:
                break
            else:
                field += line[i]
            i += 1
        if quoted:
            raise ValueError("Unterminated quoted field")
        return field.strip('"')

    i = 0
    fields = []
    while i < len(line):
        if line[i] == ' ':
            # Skip leading spaces
            i += 1
            continue
        fields.append(_parse_field())
    return fields
